@Controller()
export class OrdersEndpoint {
  constructor(@Inject("ORDERS_CLIENT") private readonly client: ClientProxy) {}

  @EventPattern("order.created")
  async handleOrderCreated(data: OrderCreated): Promise<void> {
    await this.orders.apply(data);
  }
  publish(cmd: OrderCommand): Observable<void> {
    return this.client.emit("order.command", cmd);
  }
}
